```json
/*eslint no-global-assign: "error"*/

Object = null
undefined = 1
```



```json
/*eslint no-global-assign: "error"*/
/*eslint-env browser*/

window = {}
length = 1
top = 1
```



```json
/*eslint no-global-assign: "error"*/
/*global a:readonly*/

a = 1
